// ==================== ERROR HANDLERS (MUST BE LAST) ====================

// ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ GLOBAL ERROR HANDLER
app.use((err, req, res, next) => {
  console.error('\n' + 'ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¥'.repeat(40));
  console.error('UNHANDLED ERROR IN EXPRESS');
  console.error('ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¥'.repeat(40));
  console.error('Error:', err?.message || 'Unknown');
  console.error('Name:', err?.name || 'Unknown');
  console.error('Code:', err?.code || 'None');
  console.error('Path:', req?.path || 'Unknown');
  console.error('Method:', req?.method || 'Unknown');
  console.error('User:', req?.user?.email || 'Anonymous');
  console.error('Stack:', err?.stack || 'No stack');
  console.error('ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¥'.repeat(40) + '\n');

  // Determine status code
  let statusCode = 500;
  let errorMessage = 'Internal server error';

  if (err?.name === 'ValidationError') {
    statusCode = 400;
    errorMessage = 'Validation failed';
  } else if (err?.name === 'CastError') {
    statusCode = 400;
    errorMessage = 'Invalid data format';
  } else if (err?.message?.includes('ObjectId')) {
    statusCode = 400;
    errorMessage = 'Invalid ID format';
  } else if (err?.code === 'ENOENT') {
    statusCode = 404;
    errorMessage = 'Resource not found';
  } else if (err?.code === 'ECONNREFUSED') {
    statusCode = 503;
    errorMessage = 'Service unavailable';
  }

  // Safety check - ensure response hasn't been sent
  if (res.headersSent) {
    console.error('ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¯ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â  Headers already sent, cannot send error response');
    return next(err);
  }

  // ALWAYS return JSON, never plain text
  res.status(statusCode).json({
    success: false,
    error: errorMessage,
    message: err?.message || errorMessage,
    ...(process.env.NODE_ENV === 'development' && {
      stack: err?.stack,
      code: err?.code,
      name: err?.name
    })
  });
});

// ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ 404 HANDLER (MUST BE ABSOLUTE LAST)
app.use((req, res) => {
  console.log('ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¦Ãƒâ€šÃ‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¯ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â  404 - Route not found:', req.method, req.path);

  // Safety check
  if (res.headersSent) {
    return;
  }

  res.status(404).json({
    success: false,
    error: 'Route not found',
    message: `Cannot ${req.method} ${req.path}`,
    path: req.path,
    method: req.method
  });
});

